------------------------------------------------
-- CONTENT VIEW EVENTS - bổ sung cho schema mới
-- Không thay đổi dữ liệu sample gốc phía trên.
------------------------------------------------
SELECT TOP (100)
    u.user_id,
    c.content_id,
    DATEADD(MINUTE, -(u.user_id % 60), SYSUTCDATETIME()),
    DATEADD(SECOND, 20 + ((u.user_id * 7 + c.content_id) % 161),
            DATEADD(MINUTE, -(u.user_id % 60), SYSUTCDATETIME())),
    DATEADD(SECOND, 20 + ((u.user_id * 7 + c.content_id) % 161),
            DATEADD(MINUTE, -(u.user_id % 60), SYSUTCDATETIME())),
    20 + ((u.user_id * 7 + c.content_id) % 161),
    CAST(30 + ((u.user_id * 3 + c.content_id * 5) % 71) AS DECIMAL(5,2)),
    CASE WHEN (30 + ((u.user_id * 3 + c.content_id * 5) % 71)) >= 90 THEN 1 ELSE 0 END
FROM users u
CROSS JOIN contents c
WHERE u.role_id = (SELECT TOP (1) role_id FROM roles WHERE role_name = N'User')
  AND c.status = N'published'
ORDER BY u.user_id, c.content_id;
GO

